  it('quotes commas, quotes and newlines; leaves empty labels empty', () => {
    expect(S.csvField('a,b')).toBe('"a,b"')
    expect(S.csvField('say "hi"')).toBe('"say ""hi"""')
    expect(S.csvField('x\ny')).toBe('"x\ny"')
