describe('misc', () => {
  it('formats minutes', () => {
    expect(S.formatMinutes(0)).toBe('0 min')
    expect(S.formatMinutes(59)).toBe('59 min')
    expect(S.formatMinutes(60)).toBe('1 h')
    expect(S.formatMinutes(125)).toBe('2 h 5 min')
  })
