          <label key={f.key} className="text-sm text-slate-600">
            {f.label}
            <input
              inputMode="numeric"
              value={draft[f.key]}
              onChange={(e) => edit(f.key, e.target.value)}
              onBlur={() => blur(f.key)}
              aria-invalid={!!errors[f.key]}
              className={`mt-1 w-full rounded-xl border px-3 py-3 text-base outline-none ${errors[f.key] ? 'border-red-400 bg-red-50' : 'border-slate-200 bg-slate-50 focus:border-slate-400'}`}
            />
            {errors[f.key] && <span role="alert" className="mt-1 block text-xs text-red-600">Whole number, 1 to 90</span>}
          </label>
        ))}
      </div>
    </section>
  )
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import * as T from './timer'
import StatsView from './StatsView'
import type { LogEntry, Phase, Settings, TimerState } from './timer'

const SETTINGS_KEY = 'pomodoro.settings'
const LOG_KEY = 'pomodoro.log'

function load<V>(key: string, sanitize: (raw: unknown) => V): V {
  try {
    const s = localStorage.getItem(key)
    return sanitize(s ? JSON.parse(s) : null)
  } catch {
    return sanitize(null)
  }
}
function save(key: string, value: unknown) {
  try { localStorage.setItem(key, JSON.stringify(value)) } catch { /* storage unavailable */ }
}

let audioCtx: AudioContext | null = null
function primeAudio() {
  try {
    audioCtx ??= new AudioContext()
    if (audioCtx.state === 'suspended') void audioCtx.resume()
  } catch { /* no audio */ }
}
function chime() {
  try {
    primeAudio()
    const ctx = audioCtx
    if (!ctx) return
    ;[660, 880, 1320].forEach((freq, i) => {
      const t = ctx.currentTime + i * 0.18
      const osc = ctx.createOscillator()
      const gain = ctx.createGain()
      osc.type = 'sine'
      osc.frequency.value = freq
      gain.gain.setValueAtTime(0.0001, t)
      gain.gain.exponentialRampToValueAtTime(0.25, t + 0.02)
      gain.gain.exponentialRampToValueAtTime(0.0001, t + 0.3)
      osc.connect(gain).connect(ctx.destination)
      osc.start(t)
      osc.stop(t + 0.32)
    })
  } catch { /* ignore */ }
}

const THEME: Record<Phase, { btn: string; soft: string; text: string; dot: string }> = {
  focus: { btn: 'bg-rose-500 hover:bg-rose-600', soft: 'bg-rose-50', text: 'text-rose-700', dot: 'bg-rose-500' },
  short: { btn: 'bg-teal-600 hover:bg-teal-700', soft: 'bg-teal-50', text: 'text-teal-700', dot: 'bg-teal-600' },
  long: { btn: 'bg-sky-600 hover:bg-sky-700', soft: 'bg-sky-50', text: 'text-sky-700', dot: 'bg-sky-600' },
}

export default function App() {
  const [settings, setSettings] = useState<Settings>(() => load(SETTINGS_KEY, T.sanitizeSettings))
  const [log, setLog] = useState<LogEntry[]>(() => load(LOG_KEY, T.sanitizeLog))
  const [timer, setTimer] = useState<TimerState>(() => ({
    ...T.initialState(load(SETTINGS_KEY, T.sanitizeSettings)),
    // after a reload, dots resume from today's finished sessions
    cycle: T.todaysEntries(load(LOG_KEY, T.sanitizeLog), Date.now()).length % T.CYCLE,
  }))
  const [now, setNow] = useState(() => Date.now())
  const [label, setLabel] = useState('')
  const [showSettings, setShowSettings] = useState(false)
  const [tab, setTab] = useState<'timer' | 'stats'>('timer')

  const timerRef = useRef(timer)
  const settingsRef = useRef(settings)
  const labelRef = useRef(label)
  const tabRef = useRef(tab)
  settingsRef.current = settings
  labelRef.current = label
  tabRef.current = tab

  const commit = useCallback((next: TimerState) => {
    timerRef.current = next
    setTimer(next)
    setNow(Date.now())
  }, [])

  useEffect(() => save(SETTINGS_KEY, settings), [settings])
  useEffect(() => save(LOG_KEY, log), [log])

  // Re-evaluate against the wall clock; safe to call as often as we like.
  const sync = useCallback(() => {
    const t = Date.now()
    const { state, finished } = T.tick(timerRef.current, settingsRef.current, t)
    if (finished) {
      if (!settingsRef.current.muted) chime()
      if (finished === 'focus') {
        const entry: LogEntry = { id: `${t}-${Math.random().toString(36).slice(2, 7)}`, label: labelRef.current.trim(), finishedAt: t, minutes: settingsRef.current.focus }
        setLog((l) => [...l, entry])
      }
      commit(state)
    } else {
      setNow(t)
    }
  }, [commit])

  const running = T.isRunning(timer)
  useEffect(() => {
    if (!running) return
    const id = setInterval(sync, 250)
    document.addEventListener('visibilitychange', sync)
    return () => { clearInterval(id); document.removeEventListener('visibilitychange', sync) }
  }, [running, sync])

  const toggle = useCallback(() => {
    primeAudio()
    const t = Date.now()
    commit(T.isRunning(timerRef.current) ? T.pause(timerRef.current, t) : T.start(timerRef.current, t))
  }, [commit])
  const doReset = () => commit(T.reset(timerRef.current, settingsRef.current))
  const doSkip = () => commit(T.skip(timerRef.current, settingsRef.current))

  // Space bar toggles, unless typing in a field.
  useEffect(() => {
    const isField = (e: KeyboardEvent) => {
      const el = e.target as HTMLElement | null
      // fields keep Space for typing; tabs keep it for activation; only the Timer tab uses it to start/pause
      return (
        !!el && (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA' || el.tagName === 'SELECT' || el.isContentEditable || el.getAttribute('role') === 'tab')
      ) || tabRef.current !== 'timer'
    }
    const down = (e: KeyboardEvent) => {
      if (e.code !== 'Space' || isField(e)) return
      e.preventDefault()
      if (!e.repeat) toggle()
    }
    const up = (e: KeyboardEvent) => {
      if (e.code === 'Space' && !isField(e)) e.preventDefault() // stop a focused button also "clicking"
    }
    window.addEventListener('keydown', down)
    window.addEventListener('keyup', up)
    return () => { window.removeEventListener('keydown', down); window.removeEventListener('keyup', up) }
  }, [toggle])

  const ms = T.remainingMs(timer, now)
  useEffect(() => { document.title = T.titleFor(timer, now) }, [timer, now])

  const updateSettings = (next: Settings) => {
    const old = settingsRef.current
    settingsRef.current = next
    setSettings(next)
    // An untouched (idle, full-length) phase picks up the new duration straight away.
    const cur = timerRef.current
    if (!T.isRunning(cur) && cur.remaining === T.phaseMs(old, cur.phase)) {
      commit({ ...cur, remaining: T.phaseMs(next, cur.phase) })
    }
  }

  const today = useMemo(() => T.todaysEntries(log, now), [log, now])
  const th = THEME[timer.phase]
  const dots = T.filledDots(timer)
  const total = T.phaseMs(settings, timer.phase)
  const progress = Math.min(1, Math.max(0, 1 - ms / total))
  const fmt = new Intl.DateTimeFormat(undefined, { hour: '2-digit', minute: '2-digit' })

  return (
    <div className={`min-h-screen transition-colors duration-500 ${th.soft} text-slate-800`}>
      <main className="mx-auto flex w-full max-w-md flex-col gap-6 px-4 py-6 sm:py-10">
        <header className="flex items-center justify-between">
          <h1 className="text-lg font-semibold tracking-tight">Pomodoro</h1>
          {tab === 'timer' && <div className="flex gap-2">
            <button
              type="button"
              aria-pressed={settings.muted}
              onClick={() => updateSettings({ ...settings, muted: !settings.muted })}
              className="rounded-full bg-white px-3 py-2 text-sm shadow-sm ring-1 ring-slate-200 hover:bg-slate-50"
            >
              {settings.muted ? '🔇 Muted' : '🔔 Sound on'}
            </button>
            <button
              type="button"
              aria-expanded={showSettings}
              onClick={() => setShowSettings((s) => !s)}
              className="rounded-full bg-white px-3 py-2 text-sm shadow-sm ring-1 ring-slate-200 hover:bg-slate-50"
            >
              ⚙ Settings
            </button>
          </div>}
        </header>

        <div
          role="tablist"
          aria-label="View"
          className="grid grid-cols-2 gap-1 rounded-full bg-white/70 p-1 ring-1 ring-slate-200"
          onKeyDown={(e) => {
            if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') {
              const next = tab === 'timer' ? 'stats' : 'timer'
              setTab(next)
              document.getElementById(`tab-${next}`)?.focus()
            }
          }}
        >
          {(['timer', 'stats'] as const).map((id) => (
            <button
              key={id}
              id={`tab-${id}`}
              type="button"
              role="tab"
              aria-selected={tab === id}
              tabIndex={tab === id ? 0 : -1}
              onClick={() => setTab(id)}
              className={`rounded-full px-4 py-2.5 text-sm font-semibold transition-colors ${tab === id ? `${th.btn} text-white shadow-sm` : 'text-slate-600 hover:bg-white'}`}
            >
              {id === 'timer' ? 'Timer' : 'Stats'}
            </button>
          ))}
        </div>

        {tab === 'stats' ? <StatsView log={log} /> : (<>
        {showSettings && <SettingsPanel settings={settings} onChange={updateSettings} />}

        <section className="rounded-3xl bg-white p-4 text-center sm:p-6 shadow-sm ring-1 ring-slate-200">
          <p data-testid="phase" className={`text-sm font-semibold uppercase tracking-widest ${th.text}`}>
            {T.PHASE_NAME[timer.phase]}
          </p>
          <div
            data-testid="countdown"
            role="timer"
            aria-live="off"
            className="my-3 text-[clamp(5rem,31vw,7.5rem)] font-light leading-none tabular-nums tracking-tight"
          >
            {T.formatTime(ms)}
          </div>
          <div className="mx-auto mb-5 h-1.5 w-full overflow-hidden rounded-full bg-slate-100">
            <div className={`h-full ${th.dot} transition-[width] duration-300`} style={{ width: `${progress * 100}%` }} />
          </div>

          <label className="block text-left text-sm text-slate-500">
            <span className="mb-1 block">{timer.phase === 'focus' ? 'What are you working on?' : 'Task for next focus session'}</span>
            <input
              value={label}
              onChange={(e) => setLabel(e.target.value)}
              maxLength={80}
              placeholder="Optional task label"
              className="w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-3 text-base text-slate-800 outline-none focus:border-slate-400 focus:bg-white"
            />
          </label>

          <div className="mt-5 grid grid-cols-[2fr_1fr_1fr] gap-2">
            <button type="button" onClick={toggle} className={`rounded-xl px-4 py-3.5 text-base font-semibold text-white ${th.btn}`}>
              {running ? 'Pause' : 'Start'}
            </button>
            <button type="button" onClick={doReset} className="rounded-xl bg-slate-100 px-3 py-3.5 text-base font-medium hover:bg-slate-200">
              Reset
            </button>
            <button type="button" onClick={doSkip} className="rounded-xl bg-slate-100 px-3 py-3.5 text-base font-medium hover:bg-slate-200">
              Skip
            </button>
          </div>
          <p className="mt-3 hidden text-xs text-slate-400 sm:block">Press Space to start / pause</p>

          <div className="mt-5 flex flex-col items-center gap-2" data-testid="dots">
            <div className="flex gap-2" role="img" aria-label={`${dots} of ${T.CYCLE} focus sessions done before Recharge`}>
              {Array.from({ length: T.CYCLE }, (_, i) => (
                <span key={i} data-filled={i < dots} className={`h-3 w-3 rounded-full ${i < dots ? th.dot : 'bg-slate-200'}`} />
              ))}
            </div>
            <span className="text-xs text-slate-500">{dots} of {T.CYCLE} until Recharge</span>
          </div>
        </section>

        <section className="rounded-3xl bg-white p-6 shadow-sm ring-1 ring-slate-200">
          <h2 className="mb-3 text-sm font-semibold uppercase tracking-widest text-slate-500">Today</h2>
          {today.length === 0 ? (
            <p className="text-sm text-slate-400">No focus sessions finished yet.</p>
          ) : (
            <ul data-testid="log" className="divide-y divide-slate-100">
              {[...today].reverse().map((e) => (
                <li key={e.id} className="flex items-baseline justify-between gap-3 py-2 text-sm">
                  <span className={`min-w-0 break-words ${e.label ? '' : 'italic text-slate-400'}`}>{e.label || 'Untitled session'}</span>
                  <time className="shrink-0 tabular-nums text-slate-500">{fmt.format(e.finishedAt)}</time>
                </li>
              ))}
            </ul>
          )}
          <p className="mt-3 text-xs text-slate-400">{today.length} focus session{today.length === 1 ? '' : 's'} today</p>
        </section>
      </main>
    </div>
  )
}

type Key = 'focus' | 'short' | 'long'

function SettingsPanel({ settings, onChange }: { settings: Settings; onChange: (s: Settings) => void }) {
  const fields: { key: Key; label: string }[] = [
    { key: 'focus', label: 'Focus' },
    { key: 'short', label: 'Short break' },
    { key: 'long', label: 'Recharge' },
  ]
  const [draft, setDraft] = useState({ focus: String(settings.focus), short: String(settings.short), long: String(settings.long) })
  const [errors, setErrors] = useState<Record<string, boolean>>({})

  const edit = (key: Key, raw: string) => {
    setDraft((d) => ({ ...d, [key]: raw }))
    const v = T.parseMinutes(raw)
    setErrors((e) => ({ ...e, [key]: v === null }))
    if (v !== null) onChange({ ...settings, [key]: v })
  }
  const blur = (key: Key) => {
    if (!errors[key]) return
    setDraft((d) => ({ ...d, [key]: String(settings[key]) }))
    setErrors((e) => ({ ...e, [key]: false }))
  }

  return (
    <section aria-label="Settings" className="rounded-3xl bg-white p-6 shadow-sm ring-1 ring-slate-200">
      <h2 className="mb-3 text-sm font-semibold uppercase tracking-widest text-slate-500">Durations (minutes)</h2>
      <div className="grid grid-cols-3 gap-3">
        {fields.map((f) => (
          <label key={f.key} className="text-sm text-slate-600">
            {f.label}
            <input
              inputMode="numeric"
              value={draft[f.key]}
              onChange={(e) => edit(f.key, e.target.value)}
              onBlur={() => blur(f.key)}
              aria-invalid={!!errors[f.key]}
              className={`mt-1 w-full rounded-xl border px-3 py-3 text-base outline-none ${errors[f.key] ? 'border-red-400 bg-red-50' : 'border-slate-200 bg-slate-50 focus:border-slate-400'}`}
            />
            {errors[f.key] && <span role="alert" className="mt-1 block text-xs text-red-600">Whole number, 1 to 90</span>}
          </label>
        ))}
      </div>
    </section>
  )
}

import { describe, expect, it } from 'vitest'
import * as T from './timer'

const S = T.DEFAULT_SETTINGS
const T0 = 1_000_000

describe('timer', () => {
  it('starts with 25 min focus', () => {
    const st = T.initialState(S)
    expect(st.remaining).toBe(25 * 60_000)
    expect(T.formatTime(st.remaining)).toBe('25:00')
  })
  it('is timestamp based: remaining derives from now, not tick count', () => {
    const st = T.start(T.initialState(S), T0)
    expect(T.remainingMs(st, T0 + 10 * 60_000)).toBe(15 * 60_000)
    expect(T.titleFor(st, T0 + 12 * 60_000 + 56_000)).toBe('12:04 - Focus')
  })
  it('pause freezes and resume continues', () => {
    let st = T.start(T.initialState(S), T0)
    st = T.pause(st, T0 + 60_000)
    expect(T.remainingMs(st, T0 + 999_999)).toBe(24 * 60_000)
    st = T.start(st, T0 + 500_000)
    expect(T.remainingMs(st, T0 + 500_000 + 1000)).toBe(24 * 60_000 - 1000)
  })
  it('reset restores full phase duration and stops', () => {
    let st = T.start(T.initialState(S), T0)
    st = T.reset(st, S)
    expect(st.endAt).toBeNull()
    expect(st.remaining).toBe(25 * 60_000)
  })
  it('does not finish early, finishes at endAt', () => {
    const st = T.start(T.initialState(S), T0)
    expect(T.tick(st, S, T0 + 25 * 60_000 - 1).finished).toBeNull()
    const r = T.tick(st, S, T0 + 25 * 60_000)
    expect(r.finished).toBe('focus')
    expect(r.state.phase).toBe('short')
    expect(r.state.endAt).toBeNull()
    expect(r.state.cycle).toBe(1)
  })
  it('Recharge (long break) after 4 focus sessions, then cycle resets', () => {
    let st = T.initialState(S)
    const phases: string[] = []
    for (let i = 0; i < 9; i++) {
      st = T.start(st, T0)
      st = T.tick(st, S, T0 + 90 * 60_000).state
      phases.push(st.phase)
    }
    expect(phases).toEqual(['short', 'focus', 'short', 'focus', 'short', 'focus', 'long', 'focus', 'short'])
  })
  it('dots track the cycle', () => {
    let st = T.initialState(S)
    expect(T.filledDots(st)).toBe(0)
    st = T.tick(T.start(st, 0), S, 1e9).state
    expect(T.filledDots(st)).toBe(1)
    st = { ...st, cycle: 4, phase: 'long' }
    expect(T.filledDots(st)).toBe(4)
    st = T.tick(T.start(st, 0), S, 1e9).state
    expect(T.filledDots(st)).toBe(0)
  })
  it('skip moves on without counting a focus session', () => {
    const st = T.skip(T.initialState(S), S)
    expect(st.phase).toBe('short')
    expect(st.cycle).toBe(0)
    expect(T.skip(st, S).phase).toBe('focus')
  })
  it('uses custom durations', () => {
    const s = { ...S, short: 7 }
    const st = T.tick(T.start(T.initialState(s), 0), s, 1e9).state
    expect(st.remaining).toBe(7 * 60_000)
  })
  it('formats time rounding up', () => {
    expect(T.formatTime(1)).toBe('00:01')
    expect(T.formatTime(0)).toBe('00:00')
    expect(T.formatTime(90 * 60_000)).toBe('90:00')
  })
})

describe('validation and storage', () => {
  it('parseMinutes accepts 1-90 integers only', () => {
    expect(T.parseMinutes('1')).toBe(1)
    expect(T.parseMinutes('90')).toBe(90)
    expect(T.parseMinutes(' 25 ')).toBe(25)
    for (const bad of ['0', '91', '', '-5', '2.5', 'abc', '1e1']) expect(T.parseMinutes(bad)).toBeNull()
  })
  it('sanitizeSettings falls back on bad data', () => {
    expect(T.sanitizeSettings(null)).toEqual(S)
    expect(T.sanitizeSettings({ focus: 50, short: 0, long: 'x', muted: true })).toEqual({ ...S, focus: 50, muted: true })
  })
  it('filters only entries from today', () => {
    const now = new Date(2025, 5, 10, 12).getTime()
    const log = [
      { id: 'a', label: '', finishedAt: new Date(2025, 5, 9, 23, 59).getTime() },
      { id: 'b', label: 'x', finishedAt: new Date(2025, 5, 10, 0, 1).getTime() },
    ]
    expect(T.todaysEntries(log, now).map((e) => e.id)).toEqual(['b'])
  })
  it('sanitizeLog drops junk', () => {
    expect(T.sanitizeLog('x')).toEqual([])
    expect(T.sanitizeLog([{ id: 'a', label: '', finishedAt: 1 }, { nope: 1 }, null])).toHaveLength(1)
  })
})

import { useMemo } from 'react'
import * as S from './stats'
import type { LogEntry } from './timer'

function downloadCsv(log: LogEntry[]) {
  // BOM so Excel reads non-ASCII task labels as UTF-8
  const blob = new Blob(['﻿', S.toCsv(log)], { type: 'text/csv;charset=utf-8' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = `pomodoro-sessions-${S.isoDate(Date.now())}.csv`
  document.body.appendChild(a)
  a.click()
  a.remove()
  setTimeout(() => URL.revokeObjectURL(url), 1000)
}

export default function StatsView({ log }: { log: LogEntry[] }) {
  const { days, total, streak } = useMemo(() => {
    const now = Date.now()
    const days = S.lastSevenDays(log, now)
    return { days, total: S.weekTotal(days), streak: S.currentStreak(log, now) }
  }, [log])

  const max = Math.max(60, ...days.map((d) => d.minutes))
  const W = 336, H = 200, top = 22, bottom = 28, barW = 32
  const slot = W / 7
  const plotH = H - top - bottom
  const weekday = (d: Date) => d.toLocaleDateString(undefined, { weekday: 'short' })
  const fullDate = (d: Date) => d.toLocaleDateString(undefined, { weekday: 'long', month: 'short', day: 'numeric' })

  return (
    <>
      <section className="grid grid-cols-2 gap-3">
        <div className="rounded-3xl bg-white p-4 shadow-sm ring-1 ring-slate-200 sm:p-5">
          <p className="text-xs font-semibold uppercase tracking-widest text-slate-500">This week</p>
          <p data-testid="week-total" data-minutes={total} className="mt-1 text-3xl font-light tabular-nums">{S.formatMinutes(total)}</p>
          <p className="mt-1 text-xs text-slate-400">focus, last 7 days</p>
        </div>
        <div className="rounded-3xl bg-white p-4 shadow-sm ring-1 ring-slate-200 sm:p-5">
          <p className="text-xs font-semibold uppercase tracking-widest text-slate-500">Streak</p>
          <p data-testid="streak" data-days={streak} className="mt-1 text-3xl font-light tabular-nums">
            {streak} <span className="text-base">{streak === 1 ? 'day' : 'days'}</span>
          </p>
          <p className="mt-1 text-xs text-slate-400">{streak > 0 ? 'in a row' : 'finish a session to start'}</p>
        </div>
      </section>

      <section className="rounded-3xl bg-white p-4 shadow-sm ring-1 ring-slate-200 sm:p-6">
        <h2 className="mb-3 text-sm font-semibold uppercase tracking-widest text-slate-500">Focus minutes per day</h2>
        <svg
          data-testid="chart"
          viewBox={`0 0 ${W} ${H}`}
          className="w-full"
          role="img"
          aria-label={`Focus minutes per day, last 7 days: ${days.map((d) => `${weekday(d.date)} ${d.minutes}`).join(', ')}`}
        >
          <line x1="0" x2={W} y1={top + plotH} y2={top + plotH} stroke="#e2e8f0" />
          {days.map((d, i) => {
            const h = d.minutes === 0 ? 0 : Math.max(3, (d.minutes / max) * plotH)
            const x = i * slot + (slot - barW) / 2
            const cx = i * slot + slot / 2
            return (
              <g key={d.key} data-testid="bar" data-minutes={d.minutes} data-day={S.isoDate(d.date.getTime())}>
                <title>{`${fullDate(d.date)}: ${d.minutes} min`}</title>
                <rect x={x} y={top + plotH - h} width={barW} height={h} rx="5" fill={d.isToday ? '#f43f5e' : '#fda4af'} />
                <text x={cx} y={top + plotH - h - 6} textAnchor="middle" fontSize="12" fill="#475569" className="tabular-nums">
                  {d.minutes}
                </text>
                <text x={cx} y={H - 8} textAnchor="middle" fontSize="12" fill={d.isToday ? '#be123c' : '#64748b'} fontWeight={d.isToday ? 600 : 400}>
                  {weekday(d.date)}
                </text>
              </g>
            )
          })}
        </svg>
      </section>

      <section className="rounded-3xl bg-white p-4 shadow-sm ring-1 ring-slate-200 sm:p-6">
        <div className="flex items-center justify-between gap-3">
          <div>
            <h2 className="text-sm font-semibold uppercase tracking-widest text-slate-500">History</h2>
            <p data-testid="history-count" className="mt-1 text-sm text-slate-500">
              {log.length} completed session{log.length === 1 ? '' : 's'} saved
            </p>
          </div>
          <button
            type="button"
            disabled={log.length === 0}
            onClick={() => downloadCsv(log)}
            className="shrink-0 rounded-xl bg-slate-100 px-4 py-3 text-sm font-medium hover:bg-slate-200 disabled:cursor-not-allowed disabled:opacity-50"
          >
            Export CSV
          </button>
        </div>
      </section>
    </>
  )
}

import { useMemo } from 'react'
import * as S from './stats'
import type { LogEntry } from './timer'

function downloadCsv(log: LogEntry[]) {
  // BOM so Excel reads non-ASCII task labels as UTF-8
  const blob = new Blob(['﻿', S.toCsv(log)], { type: 'text/csv;charset=utf-8' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = `pomodoro-sessions-${S.isoDate(Date.now())}.csv`
  document.body.appendChild(a)
  a.click()
  a.remove()
  setTimeout(() => URL.revokeObjectURL(url), 1000)
}

export default function StatsView({ log }: { log: LogEntry[] }) {
  const { days, total, streak } = useMemo(() => {
    const now = Date.now()
    const days = S.lastSevenDays(log, now)
    return { days, total: S.weekTotal(days), streak: S.currentStreak(log, now) }
  }, [log])

  const max = Math.max(60, ...days.map((d) => d.minutes))
  const W = 336, H = 200, top = 22, bottom = 28, barW = 32
  const slot = W / 7
  const plotH = H - top - bottom
  const weekday = (d: Date) => d.toLocaleDateString(undefined, { weekday: 'short' })
  const fullDate = (d: Date) => d.toLocaleDateString(undefined, { weekday: 'long', month: 'short', day: 'numeric' })

  return (
    <>
      <section className="grid grid-cols-2 gap-3">
        <div className="rounded-3xl bg-white p-4 shadow-sm ring-1 ring-slate-200 sm:p-5">
          <p className="text-xs font-semibold uppercase tracking-widest text-slate-500">This week</p>
          <p data-testid="week-total" data-minutes={total} className="mt-1 whitespace-nowrap text-2xl font-light tabular-nums sm:text-3xl">{S.formatMinutes(total)}</p>
          <p className="mt-1 text-xs text-slate-400">focus, last 7 days</p>
        </div>
        <div className="rounded-3xl bg-white p-4 shadow-sm ring-1 ring-slate-200 sm:p-5">
          <p className="text-xs font-semibold uppercase tracking-widest text-slate-500">Streak</p>
          <p data-testid="streak" data-days={streak} className="mt-1 text-3xl font-light tabular-nums">
            {streak} <span className="text-base">{streak === 1 ? 'day' : 'days'}</span>
          </p>
          <p className="mt-1 text-xs text-slate-400">{streak > 0 ? 'in a row' : 'finish a session to start'}</p>
        </div>
      </section>

      <section className="rounded-3xl bg-white p-4 shadow-sm ring-1 ring-slate-200 sm:p-6">
        <h2 className="mb-3 text-sm font-semibold uppercase tracking-widest text-slate-500">Focus minutes per day</h2>
        <svg
          data-testid="chart"
          viewBox={`0 0 ${W} ${H}`}
          className="w-full"
          role="img"
          aria-label={`Focus minutes per day, last 7 days: ${days.map((d) => `${weekday(d.date)} ${d.minutes}`).join(', ')}`}
        >
          <line x1="0" x2={W} y1={top + plotH} y2={top + plotH} stroke="#e2e8f0" />
          {days.map((d, i) => {
            const h = d.minutes === 0 ? 0 : Math.max(3, (d.minutes / max) * plotH)
            const x = i * slot + (slot - barW) / 2
            const cx = i * slot + slot / 2
            return (
              <g key={d.key} data-testid="bar" data-minutes={d.minutes} data-day={S.isoDate(d.date.getTime())}>
                <title>{`${fullDate(d.date)}: ${d.minutes} min`}</title>
                <rect x={x} y={top + plotH - h} width={barW} height={h} rx="5" fill={d.isToday ? '#f43f5e' : '#fda4af'} />
                <text x={cx} y={top + plotH - h - 6} textAnchor="middle" fontSize="12" fill="#475569" className="tabular-nums">
                  {d.minutes}
                </text>
                <text x={cx} y={H - 8} textAnchor="middle" fontSize="12" fill={d.isToday ? '#be123c' : '#64748b'} fontWeight={d.isToday ? 600 : 400}>
                  {weekday(d.date)}
                </text>
              </g>
            )
          })}
        </svg>
      </section>

      <section className="rounded-3xl bg-white p-4 shadow-sm ring-1 ring-slate-200 sm:p-6">
        <div className="flex items-center justify-between gap-3">
          <div>
            <h2 className="text-sm font-semibold uppercase tracking-widest text-slate-500">History</h2>
            <p data-testid="history-count" className="mt-1 text-sm text-slate-500">
              {log.length} completed session{log.length === 1 ? '' : 's'} saved
            </p>
          </div>
          <button
            type="button"
            disabled={log.length === 0}
            onClick={() => downloadCsv(log)}
            className="shrink-0 rounded-xl bg-slate-100 px-4 py-3 text-sm font-medium hover:bg-slate-200 disabled:cursor-not-allowed disabled:opacity-50"
          >
            Export CSV
          </button>
        </div>
      </section>
    </>
  )
}

